  function makeVakantiebijslag(store2) {
    const t = store2.translate;
    return {
      menuLabel: t("Vakantiebijslag"),
      subSections: [
        {
          menuLabel: t("Vakantiebijslag"),
          blocks: [
            {
              type: "block",
              items: [
                {
                  type: "radio",
                  question: t("Is er een vakantiebijslag?"),
                  slug: "vakantiebijslag/ja-nee",
                  options: [
                    { label: t("Ja"), value: "ja" },
                    { label: t("Nee"), value: "nee" }
                  ],
                  setuPath: ["holidayAllowance", HOLIDAY_ALLOWANCE_PERCENTAGE_PERIOD],
                  convertSetuValue: (value, context) => {
                    if (value !== "ja") return null;
                    let allowance = {
                      name: t("Vakantiebijslag"),
                      origin: { type: TODO_REPLACE_WITH_REAL_ORIGIN },
                      line: [getLineAmountAnswer(store2, "vakantiebijslag")]
                    };
                    return allowance;
                  }
                }
              ]
            },
            {
              type: "block",
              showIf: { slug: "vakantiebijslag/ja-nee", answer: "ja" },
              items: [
                ...makeLineAmountQuestions(store2, "vakantiebijslag", t("Hoeveel bedraagt de vakantiebijslag?"), {
                  includeFixedAmountQuestions: false,
                  includeTimeQuestions: false
                })
              ]
            }
          ]
        }
      ]
    };
  }

