  // src/definition/11_pensioen.tsx
  function makePensioen(store2) {
    const t = store2.translate;
    return {
      menuLabel: t("Pensioen"),
      subSections: [
        {
          menuLabel: "",
          blocks: [
            { type: "header", text: t("Pensioen") },
            {
              type: "block",
              items: [
                {
                  type: "radio",
                  question: t("Ken je een pensioenregeling?"),
                  slug: "pensioenregeling/van-toepassing",
                  options: [
                    { label: t("Ja"), value: "ja" },
                    { label: t("Nee"), value: "nee" }
                  ],
                  setuPath: ["pension", 0],
                  convertSetuValue: (value) => {
                    if (value !== "ja") return null;
                    const line = {
                      amount: {
                        value: toFloat(store2.getAnswer("pensioenregeling/werkgeverspremie/percentage")),
                        unitCode: "Percentage",
                        baseAmount: {
                          unitCode: "YearlyRate",
                          baseType: "Pension"
                        }
                      },
                      interval: { value: 1, unitCode: "Year" },
                      contributionSource: "Employer",
                      conditions: []
                    };
                    let pension = {
                      name: store2.getAnswer("pensioenregeling/pensioenfonds/naam")?.toString() || "Pensioenregeling",
                      origin: { type: TODO_REPLACE_WITH_REAL_ORIGIN },
                      line: [line]
                    };
                    if (store2.getAnswer("pensioenregeling/franchise/van-toepassing") === "ja") {
                      pension.franchise = {
                        description: store2.getAnswer("pensioenregeling/franchise/namelijk")?.toString()
                      };
                    }
                    return pension;
                  }
                }
              ]
            },
            {
              type: "block",
              showIf: {
                slug: "pensioenregeling/van-toepassing",
                answer: "ja"
              },
              items: [
                {
                  type: "text",
                  slug: "pensioenregeling/pensioenfonds/naam",
                  question: t("Wat is de naam van het pensioenfonds?")
                }
              ]
            },
            {
              type: "block",
              title: t("Wat is de hoogte van de werkgeverspremie?"),
              showIf: {
                slug: "pensioenregeling/van-toepassing",
                answer: "ja"
              },
              items: [
                {
                  type: "text",
                  slug: "pensioenregeling/werkgeverspremie/percentage",
                  restrictTo: "float",
                  postfix: "%",
                  questionAfter: t("van de pensioengrondslag"),
                  inline: true
                },
                {
                  type: "alert",
                  text: "De grondslag wordt later in het formulier uitgevraagd"
                }
              ]
            },
            {
              type: "block",
              title: t("Hanteer je een franchise?"),
              showIf: {
                slug: "pensioenregeling/van-toepassing",
                answer: "ja"
              },
              items: [
                {
                  type: "radio",
                  slug: "pensioenregeling/franchise/van-toepassing",
                  options: [
                    { label: t("Ja, namelijk:"), value: "ja" },
                    { label: t("Nee"), value: "nee" }
                  ]
                },
                {
                  type: "text",
                  textarea: true,
                  placeholder: "Geef een beschrijving van de franchise",
                  slug: "pensioenregeling/franchise/namelijk",
                  renderBelow: "showIf",
                  showIf: {
                    slug: "pensioenregeling/franchise/van-toepassing",
                    answer: "ja"
                  }
                }
              ]
            }
          ]
        }
      ]
    };
  }

