  // src/definition/15_grondslagen.tsx
  function makeGrondslagen(store2) {
    const t = store2.translate;
    const toeslagRows = makeToeslagRows(store2);
    const aanvullendeSocialeZekerheidsRegelingenRows = makeAanvullendeRegelingenRows(store2);
    let grondslagCodesRaw = [
      store2.getAnswer("vakantiebijslag/percentage/grondslag")?.toString(),
      store2.getAnswer("individueel-keuzebudget/percentage/grondslag")?.toString(),
      store2.getAnswer("pensioenregeling") === "ja" ? "Pension" : null
    ];
    for (const row of toeslagRows) {
      const numVariations = store2.countAnswerRows(row.slug);
      for (let i2 = 0; i2 < numVariations; i2++) {
        grondslagCodesRaw.push(store2.getAnswer([row.slug, i2, "percentage/grondslag"])?.toString() || null);
      }
    }
    for (let i2 = 0; i2 < store2.countAnswerRows("loondoorbetaling-bij-ziekte"); i2++) {
      grondslagCodesRaw.push(store2.getAnswer(["loondoorbetaling-bij-ziekte", i2, "grondslag"])?.toString() || null);
    }
    for (const row of aanvullendeSocialeZekerheidsRegelingenRows) {
      grondslagCodesRaw.push(store2.getAnswer(row.slug + "/werkgeverspremie/percentage/grondslag")?.toString() || null);
      grondslagCodesRaw.push(store2.getAnswer(row.slug + "/werknemerspremie/percentage/grondslag")?.toString() || null);
    }
    const numAnders = store2.countAnswerRows("andere-sociale-regelingen");
    for (let i2 = 0; i2 < numAnders; i2++) {
      grondslagCodesRaw.push(store2.getAnswer(["andere-sociale-regelingen", i2, "werkgeverspremie", 0, "percentage/grondslag"])?.toString() || null);
      grondslagCodesRaw.push(store2.getAnswer(["andere-sociale-regelingen", i2, "werknemerspremie", 0, "percentage/grondslag"])?.toString() || null);
    }
    const numOther = store2.countAnswerRows("overige-regelingen");
    for (let i2 = 0; i2 < numOther; i2++) {
      grondslagCodesRaw.push(store2.getAnswer(["overige-regelingen", i2, "percentage/grondslag"])?.toString() || null);
    }
    let grondslagCodes = grondslagCodesRaw.filter(removeNullish).filter(unique2);
    if (grondslagCodes.length === 0) {
      return null;
    }
    const section = {
      menuLabel: t("Grondslagen"),
      subSections: []
    };
    for (const [index3, code] of grondslagCodes.entries()) {
      const subSection = {
        menuLabel: baseDef2Label(code),
        blocks: [
          {
            type: "block",
            items: [
              {
                type: "header",
                text: t("Grondslag {label}", { label: baseDef2Label(code) }),
                level: 3
              },
              {
                type: "checkbox",
                slug: `grondslag/${code}/salaris`,
                label: t("Salaris wordt meegenomen bij deze grondslag"),
                shouldConvertNullSetuValue: true,
                setuPath: ["baseDefinition", index3],
                convertSetuValue: (value, context) => {
                  const baseDef = {
                    baseType: code,
                    remunerationIndicator: store2.getAnswer(`grondslag/${code}/salaris`) === CHECKED,
                    holidayAllowanceIndicator: store2.getAnswer(`grondslag/${code}/vakantietoeslag`) === CHECKED,
                    paidLeaveDayIndicator: store2.getAnswer(`grondslag/${code}/betaald-verlof`) === CHECKED,
                    allAllowancesIndicator: store2.getAnswer(`grondslag/${code}/toeslagen`)?.toString() === "all"
                  };
                  const peilDatum = store2.getAnswer(`grondslag/${code}/peildatum`);
                  if (peilDatum) {
                    baseDef.referenceDate = {
                      occurrenceType: "Recurring",
                      interval: `R/${toDateString(peilDatum)}/P1Y`
                    };
                  }
                  if (store2.getAnswer(`grondslag/${code}/toeslagen`)?.toString() === "some") {
                    baseDef.allowances = toeslagRows.filter((row) => store2.getAnswer(`grondslag/${code}/toeslag-${row.slug}`) === CHECKED).map((row) => ({ typeCode: row.typeCode }));
                  }
                  return baseDef;
                }
              },
              {
                type: "checkbox",
                slug: `grondslag/${code}/vakantietoeslag`,
                label: t("Vakantietoeslag wordt meegenomen bij deze grondslag")
              },
              {
                type: "checkbox",
                slug: `grondslag/${code}/betaald-verlof`,
                label: t("Betaald verlof wordt meegenomen bij deze grondslag")
              },
              {
                type: "radio",
                question: t("Worden toeslagen meegenomen bij deze grondslag?"),
                slug: `grondslag/${code}/toeslagen`,
                options: [
                  { label: t("Alle toeslagen"), value: "all" },
                  { label: t("Geen toeslagen"), value: "none" },
                  { label: t("Sommige toeslagen:"), value: "some" }
                ]
              },
              ...toeslagRows.map(
                (row) => ({
                  type: "checkbox",
                  slug: `grondslag/${code}/toeslag-${row.slug}`,
                  label: row.label,
                  showIf: { slug: `grondslag/${code}/toeslagen`, answer: "some" },
                  renderBelow: "showIf"
                })
              ),
              {
                type: "date",
                slug: `grondslag/${code}/peildatum`,
                question: t("Peildatum voor deze grondslag"),
                optional: true
              }
            ]
          }
        ]
      };
      section.subSections.push(subSection);
    }
    return section;
  }

  // src/definition/sections.ts
